/* Count the lookup's final preemption check, and record what it left behind.

   The lookup calls this once, on its way out, after restoring the preemption count it
   raised on the way in. Counting it is how a case tells a request the dispatch layer
   refused from one it let through: a refusal returns before the lookup is entered at
   all. Recording the preemption count as the lookup leaves it is how the run as a whole
   asserts that the hold is balanced.  */

static ULONG    test_lookup_exits;
static ULONG    test_preempt_disable_on_exit;

VOID  _tx_thread_system_preempt_check(VOID)
{
    test_lookup_exits++;
    test_preempt_disable_on_exit =  (ULONG) _tx_thread_preempt_disable;
}


